/* -------------------- official names and forms -------------------- */
const NAME_FIX={29:'Nidoran♀',32:'Nidoran♂',83:"Farfetch'd",122:'Mr. Mime',439:'Mime Jr.',669:'Flabébé',772:'Type: Null',785:'Tapu Koko',786:'Tapu Lele',787:'Tapu Bulu',788:'Tapu Fini',865:"Sirfetch'd",866:'Mr. Rime',984:'Great Tusk',985:'Scream Tail',986:'Brute Bonnet',987:'Flutter Mane',988:'Slither Wing',989:'Sandy Shocks',990:'Iron Treads',991:'Iron Bundle',992:'Iron Hands',993:'Iron Jugulis',994:'Iron Moth',995:'Iron Thorns',1001:'Wo-Chien',1002:'Chien-Pao',1003:'Ting-Lu',1004:'Chi-Yu',1005:'Roaring Moon',1006:'Iron Valiant',1009:'Walking Wake',1010:'Iron Leaves',1020:'Gouging Fire',1021:'Raging Bolt',1022:'Iron Boulder',1023:'Iron Crown'};
const SLUG_FIX={29:'nidoranf',32:'nidoranm',83:'farfetchd',122:'mrmime',439:'mimejr',669:'flabebe',772:'typenull',785:'tapukoko',786:'tapulele',787:'tapubulu',788:'tapufini',865:'sirfetchd',866:'mrrime',984:'greattusk',985:'screamtail',986:'brutebonnet',987:'fluttermane',988:'slitherwing',989:'sandyshocks',990:'irontreads',991:'ironbundle',992:'ironhands',993:'ironjugulis',994:'ironmoth',995:'ironthorns',1001:'wochien',1002:'chienpao',1003:'tinglu',1004:'chiyu',1005:'roaringmoon',1006:'ironvaliant',1009:'walkingwake',1010:'ironleaves',1020:'gougingfire',1021:'ragingbolt',1022:'ironboulder',1023:'ironcrown'};
const oldName=window.getPokeName, oldSlug=window.getShowdownName;
window.getPokeName=function(id){id=Number(id);return NAME_FIX[id]||oldName?.(id)||window.ALL_POKE_NAMES?.[id]||`Pokémon ${id}`};
window.getShowdownName=function(id){id=Number(id);if(SLUG_FIX[id])return SLUG_FIX[id];try{return oldSlug?.(id)||window.getPokeName(id).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'')}catch(e){return 'bulbasaur'}};
try{getPokeName=window.getPokeName;getShowdownName=window.getShowdownName}catch(e){}
if(window.ALL_POKE_NAMES)Object.entries(NAME_FIX).forEach(([id,n])=>ALL_POKE_NAMES[id]=n);

const OFFICIAL_MEGA=[3,6,9,15,18,65,80,94,115,127,130,142,150,181,208,212,214,229,248,254,257,260,282,302,303,306,308,310,319,323,334,354,359,362,373,376,380,381,384,428,445,448,460,475,531,719];
const OFFICIAL_MEGA_SET=new Set(OFFICIAL_MEGA);
window.MEGA_POKES=OFFICIAL_MEGA.slice();
if(window.MEGA_XY){Object.keys(MEGA_XY).forEach(k=>{if(!OFFICIAL_MEGA_SET.has(Number(k)))delete MEGA_XY[k]});}
function cleanInvalidMegas(){ensureCore();[...(P.team||[]),...(P.box||[])].forEach(p=>{if(!p?.id)return;if(p.isMega&&!OFFICIAL_MEGA_SET.has(Number(p.id))&&!p.psyMega){p.isMega=false;p.mega=false;p.megaForm=null;p.name=window.getPokeName(p.id);try{window.recalcPoke?.(p)}catch(e){}}else if(!p.psyFormLabel)p.name=window.getPokeName(p.id);});}
const ironIds=new Set([990,991,992,993,994,995,1006,1010,1022,1023]);
const oldReal=window.getRealSprite;
function pokeApiStatic(id,shiny=false){return `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${shiny?'shiny/':''}${Number(id)}.png`}
window.getRealSprite=function(p){if(typeof p==='number')p={id:p};p=p||{};const id=Number(p.id||1);if(ironIds.has(id))return pokeApiStatic(id,!!p.shiny);try{return oldReal?.(p)||pokeApiStatic(id,!!p.shiny)}catch(e){return pokeApiStatic(id,!!p.shiny)}};
window.psyWorldSprite=p=>pokeApiStatic(Number(p?.id||1),!!p?.shiny);
try{getRealSprite=window.getRealSprite}catch(e){}

/* -------------------- evolution stage / shiny evolution -------------------- */
const EXTRA_EVO={624:625,625:983,996:997,997:998,957:958,958:959,932:933,933:934,938:939,940:941,942:943,944:945,946:947,948:949,953:954,955:956,969:970,971:972,974:975,999:1000,1011:1019,1018:null};
function evoGraphs(){const next={},prev={};try{Object.entries(EVOLUTION_MAP||{}).forEach(([a,v])=>{if(v?.to){next[+a]=+v.to;prev[+v.to]=+a}});Object.entries(SPECIAL_EVOLUTIONS||{}).forEach(([a,opts])=>Object.values(opts||{}).forEach(v=>{if(v?.to&&!prev[+v.to])prev[+v.to]=+a}))}catch(e){}Object.entries(EXTRA_EVO).forEach(([a,b])=>{if(b){next[+a]=+b;prev[+b]=+a}});return{next,prev}}
window.getEvoStage=function(id){id=Number(id);const {prev}=evoGraphs();let s=1,cur=id,guard=0;while(prev[cur]&&guard++<4){s++;cur=prev[cur]}return clamp(s,1,3)};
window.getStageMult=id=>window.getEvoStage(id)===3?1.8:window.getEvoStage(id)===2?1.4:1;
function evoBaseline(id){const s=window.getEvoStage(id);return s===3?2.24:s===2?1.4:1}
function normalizeEvolutionBonuses(){ensureCore();[...(P.team||[]),...(P.box||[])].forEach(p=>{if(!p?.id)return;p.evoMult=Math.max(Number(p.evoMult||1),evoBaseline(p.id));try{window.recalcPoke?.(p)}catch(e){}})}
function shinyEvoReq(p){try{const id=Number(p?.id),e=EVOLUTION_MAP?.[id];if(!e?.to)return null;const to=Number(e.to),min=Number(e.minLevel||1),tier=String(window.getTier?.(to,false,false,false)||'E'),cost=Math.max(10,Number(window.getShinyStoneCost?.(to)||window.getTierCost?.(to)||10));return{to,min,cost,tier,stone:'Shiny Stone'}}catch(e){return null}}
window.useShinyStone=function(idx,isBox){ensureCore();const p=isBox?P.box?.[idx]:P.team?.[idx];if(!p)return toast('Pokémon não encontrado.');const have=Number(P.inventory['Shiny Stone']||0);if(!p.shiny){const cost=Math.max(10,Number(window.getShinyStoneCost?.(p)||window.getTierCost?.(p.id)||10));if(have<cost)return toast(`Precisa ${cost} Shiny Stone.`);P.inventory['Shiny Stone']-=cost;if(P.inventory['Shiny Stone']<=0)delete P.inventory['Shiny Stone'];p.shiny=true;p.name=window.getPokeName(p.id);try{p.tier=window.getTier?.(p.id,true,!!p.isMega,false);window.recalcPoke?.(p)}catch(e){}save();try{window.renderTeam?.()}catch(e){}toast(`✨ ${p.name} agora é Shiny!`);return setTimeout(()=>window.openPokeDetail?.(idx,isBox),100)}const r=shinyEvoReq(p);if(!r)return toast('Este Shiny já está na forma final.');if(Number(p.level||1)<r.min)return toast(`Precisa Lv.${r.min}. Atual Lv.${p.level}.`);if(have<r.cost)return toast(`Precisa ${r.cost} Shiny Stone.`);P.inventory['Shiny Stone']-=r.cost;if(P.inventory['Shiny Stone']<=0)delete P.inventory['Shiny Stone'];const old=window.getPokeName(p.id);p.id=r.to;p.name=window.getPokeName(r.to);p.type=window.TYPE_BY_ID_ALL?.[r.to]||window.TYPE_BY_ID_FULL?.[r.to]||p.type;p.isMega=false;p.megaForm=null;p.level=1;p.exp=0;p.maxExp=100;p.evoMult=Math.max(Number(p.evoMult||1)*(EVOLUTION_MAP?.[r.to]?1.4:1.6),evoBaseline(r.to));try{p.moves=window.getMovesForLevel?.(r.to,1)||p.moves;p.movePool=window.getFullMoveList?.(r.to,1)||p.moves;p.tier=window.getTier?.(r.to,true,false,false);window.recalcPoke?.(p)}catch(e){}save();try{window.renderTeam?.()}catch(e){}toast(`✨ ${old} evoluiu para Shiny ${p.name}!`);setTimeout(()=>window.openPokeDetail?.(idx,isBox),100)};
window.psyTreeMakeShiny=(idx,isBox)=>window.useShinyStone(idx,isBox);

/* boost details + evolution button adjustments */
const oldDetail=window.openPokeDetail;
window.openPokeDetail=function(idx,isBox){const r=oldDetail?.apply(this,arguments);setTimeout(()=>{const p=isBox?P.box?.[idx]:P.team?.[idx],host=$('detail-poke-content');if(!p||!host)return;host.querySelector('#psy19-boost-box')?.remove();let st;try{st=window.calcDetailedStats?.(p)}catch(e){}if(st){const formMult=(p.shiny&&p.isMega)?3:1,baseHpNoBoost=Math.floor(st.baseHp*st.resetMult*st.evoMult*formMult),baseAtkNoBoost=Math.floor(st.baseAtk*st.resetMult*st.evoMult*formMult),gainHp=Math.max(0,st.afterBoostHp-baseHpNoBoost),gainAtk=Math.max(0,st.afterBoostAtk-baseAtkNoBoost);const b=D.createElement('div');b.id='psy19-boost-box';b.innerHTML=`<div>💪 Boost atual: <b>${Number(p.boost||0)}/100</b></div><div>Evolução real: <b>estágio ${window.getEvoStage(p.id)} • x${Number(p.evoMult||1).toFixed(2)}</b></div><div>❤ Vida recebida pelo Boost: <b>+${fmt(gainHp)}</b></div><div>⚔ Dano/ATK recebido pelo Boost: <b>+${fmt(gainAtk)}</b></div>`;const anchor=host.querySelector('.psy-detail-calc,.psy-v10-calc')||host.children[1];anchor?.after?.(b)||host.prepend(b)}},40);return r};

/* -------------------- Darkness Stone replaces Darkness Stone -------------------- */
function migrateGhostStone(){ensureCore();const q=Number(P.inventory['Ghost Stone']||0)+Number(P.inventory['Dark Stone']||0);if(q>0)P.inventory['Darkness Stone']=Number(P.inventory['Darkness Stone']||0)+q;delete P.inventory['Ghost Stone'];delete P.inventory['Dark Stone'];try{if(EVOLUTION_MAP?.[92])EVOLUTION_MAP[92].stone='Darkness Stone';if(EVOLUTION_MAP?.[93])EVOLUTION_MAP[93].stone='Darkness Stone'}catch(e){}try{if(Array.isArray(STONE_DATA)){const i=STONE_DATA.indexOf('Darkness Stone');if(i>=0)STONE_DATA.splice(i,1)}}catch(e){}try{if(window.TYPE_TO_STONE){TYPE_TO_STONE.Fantasma='Darkness Stone';TYPE_TO_STONE.Ghost='Darkness Stone';TYPE_TO_STONE.Sombrio='Darkness Stone';TYPE_TO_STONE.Dark='Darkness Stone'}}catch(e){}try{if(Array.isArray(window.SHOP_DG))for(let i=SHOP_DG.length-1;i>=0;i--){if(SHOP_DG[i]?.n==='Darkness Stone'||/Pack Cards/i.test(SHOP_DG[i]?.n||''))SHOP_DG.splice(i,1)}}catch(e){} }
const oldGetStone=window.getStoneForType;
window.getStoneForType=function(type){const t=String(type||'').toLowerCase();if(t.includes('ghost')||t.includes('fantasma')||t.includes('dark')||t.includes('sombr'))return 'Darkness Stone';return oldGetStone?.(type)||'Heart Stone'};

/* item selling protection: quest + craft materials never sell */
