/* -------------------- Egg system: timed drops, instant shop -------------------- */
const EGG_TIERS={E:{min:5,c:'#7dd3fc'},D:{min:7,c:'#93c5fd'},C:{min:10,c:'#a78bfa'},B:{min:15,c:'#c084fc'},A:{min:30,c:'#f472b6'},S:{min:60,c:'#ef4444'},SS:{min:0,c:'#facc15'},SSS:{min:0,c:'#22d3ee'},UR:{min:0,c:'#a78bfa'},'UR+':{min:0,c:'#e879f9'},'UR++':{min:0,c:'#ffffff'}};
const REGIONS={KANTO:[1,151],JOHTO:[152,251],HOENN:[252,386],SINNOH:[387,493],UNOVA:[494,649],KALOS:[650,721],ALOLA:[722,809],GALAR:[810,898],PALDEA:[906,1025]};
const EGG_TYPE_ALIASES={Normal:['normal'],Fire:['fire','fogo'],Water:['water','agua','água'],Grass:['grass','planta'],Electric:['electric','eletrico','elétrico'],Ice:['ice','gelo'],Fighting:['fighting','lutador'],Poison:['poison','veneno','venenoso'],Ground:['ground','terra'],Flying:['flying','voador'],Psychic:['psychic','psiquico','psíquico'],Bug:['bug','inseto'],Rock:['rock','pedra'],Ghost:['ghost','fantasma'],Dragon:['dragon','dragao','dragão'],Dark:['dark','noturno','sombrio'],Steel:['steel','aco','aço','metal'],Fairy:['fairy','fada']};
function eggState(){ensureCore();const EGG_INC_SLOTS=8;P.eggV19=P.eggV19||{bag:[],inc:Array(EGG_INC_SLOTS).fill(null),ko:0,log:[]};const s=P.eggV19;if(!Array.isArray(s.bag))s.bag=[];if(!Array.isArray(s.inc))s.inc=[];while(s.inc.length<EGG_INC_SLOTS)s.inc.push(null);if(s.inc.length>EGG_INC_SLOTS){const overflow=s.inc.splice(EGG_INC_SLOTS).filter(Boolean);if(overflow.length)s.bag.push(...overflow)}if(!Array.isArray(s.log))s.log=[];if(!P.meta.eggV19Migrated){const conv=o=>{if(!o)return null;let kind='random',value='';const nm=String(o.name||o.kind||o.type||'');if(o.region||/KANTO|JOHTO|HOENN|SINNOH|UNOVA|KALOS|ALOLA|GALAR|PALDEA/i.test(nm)){kind='region';value=String(o.region||nm.match(/KANTO|JOHTO|HOENN|SINNOH|UNOVA|KALOS|ALOLA|GALAR|PALDEA/i)?.[0]||'KANTO').toUpperCase()}else if(o.element||o.typeName||/Fire|Water|Grass|Electric|Ice|Fighting|Poison|Ground|Flying|Psychic|Bug|Rock|Ghost|Dragon|Dark|Steel|Fairy|Fogo|Agua|Água|Planta|Eletrico|Elétrico|Gelo|Fantasma|Dragao|Dragão|Sombrio/i.test(nm)){kind='element';const raw=String(o.element||o.typeName||nm);const mm=Object.keys(EGG_TYPE_ALIASES).find(k=>EGG_TYPE_ALIASES[k].some(a=>raw.toLowerCase().includes(a)))||'Normal';value=mm}const tier=EGG_TIERS[o.tier]?o.tier:'E';return makeEgg({kind,value,tier,source:'legacy',instant:false})};try{for(const o of (P.eggs||[])){const e=conv(o);if(e)s.bag.push(e)}P.eggs=[]}catch(e){}try{const old=P.eggSystem;if(old){for(const o of (old.inventory||[])){const e=conv(o);if(e)s.bag.push(e)}for(const o of (old.incubators||[])){const e=conv(o);if(e)s.bag.push(e)}old.inventory=[];old.incubators=Array(8).fill(null)}}catch(e){}P.meta.eggV19Migrated=true;save()}return s}
function eggTierRoll(){const r=Math.random()*100;return r<36?'E':r<62?'D':r<80?'C':r<92?'B':'A'}
function makeEgg(o={}){const tier=o.tier||eggTierRoll(),instant=!!o.instant;return{id:'e19_'+Date.now().toString(36)+Math.random().toString(36).slice(2,7),kind:o.kind||'random',value:o.value||'',tier,source:o.source||'drop',instant,dur:instant?0:(EGG_TIERS[tier]?.min||5)*60000,start:0,ready:0}}
function allIds(){let src={};try{src=(typeof ALL_POKE_NAMES!=='undefined'?ALL_POKE_NAMES:(window.ALL_POKE_NAMES||{}))||{}}catch(e){src=window.ALL_POKE_NAMES||{}}const ids=Object.keys(src).map(Number).filter(n=>n>0&&n<=1025);return ids.length?ids:Array.from({length:1025},(_,i)=>i+1)}
function isLegend(id){try{return LEGENDARY_IDS?.has(Number(id))}catch(e){return false}}
const PSY_EGG_TIER_RANK={E:0,D:1,C:2,B:3,A:4,S:5,SS:6,SSS:7,UR:8,'UR+':9,'UR++':10};
function eggTierPool(t){
  t=String(t||'E');const ids=allIds(),normal=ids.filter(id=>id!==54&&!psyTierIsLegend(id)&&!psyTierIsBossSpecies(id));
  if(t==='SSS'){let a=[];try{a=[...(window.OFFICIAL_MEGA_SET||OFFICIAL_MEGA_SET||[])].map(Number)}catch(e){}return a.filter(id=>normal.includes(id)&&!psyTierIsLegend(id));}
  if(t==='UR')return ids.filter(id=>psyTierIsBossSpecies(id)&&!psyTierIsLegend(id));
  if(t==='UR+')return ids.filter(id=>psyTierIsLegend(id));
  if(t==='UR++')return ids.filter(id=>psyTierIsLegend(id));
  return normal.filter(id=>getBaseTier(id)===t);
}
function eggSpecialPool(mode){
  const ids=allIds(),rank=PSY_EGG_TIER_RANK;mode=String(mode||'');
  if(mode==='shiny')return ids.filter(id=>id!==54&&!psyTierIsLegend(id)&&!psyTierIsBossSpecies(id)&&(rank[getBaseTier(id)]??99)<=rank.S);
  if(mode==='boss')return ids.filter(id=>psyTierIsBossSpecies(id)&&!psyTierIsLegend(id));
  if(mode==='legendary'||mode==='shinyLegendary')return ids.filter(id=>psyTierIsLegend(id));
  if(mode==='mega'||mode==='shinyMega'){let a=[];try{a=[...(window.OFFICIAL_MEGA_SET||OFFICIAL_MEGA_SET||[])].map(Number)}catch(e){}return a.filter(id=>ids.includes(id)&&id!==54&&!psyTierIsLegend(id)&&!psyTierIsBossSpecies(id));}
  return [];
}
function typeOf(id){let t='';try{t=(typeof TYPE_BY_ID_ALL!=='undefined'?TYPE_BY_ID_ALL?.[id]:'')||window.TYPE_BY_ID_FULL?.[id]||window.TYPE_BY_ID_ALL?.[id]||''}catch(e){t=window.TYPE_BY_ID_FULL?.[id]||window.TYPE_BY_ID_ALL?.[id]||''}return String(t||'Normal').toLowerCase()}
function eggPool(e){
  if(e.kind==='special')return eggSpecialPool(e.value);
  if(e.kind==='tier')return eggTierPool(e.tier);
  let ids=allIds().filter(id=>id!==54&&!psyTierIsLegend(id)&&!psyTierIsBossSpecies(id)&&(PSY_EGG_TIER_RANK[getBaseTier(id)]??99)<=PSY_EGG_TIER_RANK.A);
  if(e.kind==='region'){const [a,b]=REGIONS[e.value]||REGIONS.KANTO;ids=ids.filter(id=>id>=a&&id<=b)}
  if(e.kind==='element'){const al=EGG_TYPE_ALIASES[e.value]||[String(e.value).toLowerCase()];ids=ids.filter(id=>al.some(x=>typeOf(id).includes(x)))}
  if(e.kind==='random'&&e.source!=='shop')ids=eggTierPool(e.tier);
  if(!ids.length)ids=eggTierPool('E');return ids
}
function addDropEgg(o={}){const s=eggState(),e=makeEgg({...o,instant:false});s.bag.push(e);s.log.unshift({t:Date.now(),m:`${eggName(e)} recebido`});s.log=s.log.slice(0,20);save();toast(`🥚 Você encontrou um ${eggName(e)}!`);return e}
function eggName(e){if(e.kind==='region')return `${e.value} Egg • E–A`;if(e.kind==='element')return `${e.value} Egg • E–A`;if(e.kind==='special'){const n={shiny:'Shiny Egg',mega:'Mega Egg',boss:'Boss Egg',legendary:'Legendary Egg',shinyMega:'Shiny Mega Egg',shinyLegendary:'Shiny Legendary Egg'};return n[e.value]||'Special Egg'}if(e.kind==='tier')return `Egg Tier ${e.tier}`;return e.source==='shop'?'Mystery Egg • E–A':`Mystery Egg • ${e.tier}`}
function eggRarityForTier(tier){
  const names=PSY_TIER_RARITY_WINDOW?.[tier]||['Lixo'];if(names.length===1)return {...psyFindRarityByName(names[0])};
  const chance={E:.16,D:.18,C:.20,B:.22,A:.24,S:.24,SS:.20,SSS:.18,UR:.14,'UR+':.06}[tier]??.18;
  return {...psyFindRarityByName(Math.random()<chance?names[1]:names[0])};
}
function hatchEgg(e){
  const pool=eggPool(e),id=Number(pool[Math.floor(Math.random()*pool.length)]||1);let shiny=false,mega=false,boss=false,tier=e.kind==='tier'?e.tier:getBaseTier(id);
  if(e.kind==='special'){
    shiny=e.value==='shiny'||e.value==='shinyMega'||e.value==='shinyLegendary';mega=e.value==='mega'||e.value==='shinyMega';boss=e.value==='boss';
    tier=e.value==='mega'?'SSS':e.value==='boss'?'UR':(e.value==='legendary'||e.value==='shinyMega')?'UR+':e.value==='shinyLegendary'?'UR++':getTier(id,true,false,false);
  }else if(e.kind==='tier'){
    if(e.tier==='SSS')mega=true;else if(e.tier==='UR')boss=true;else if(e.tier==='UR++')shiny=true;
  }
  tier=e.kind==='special'?tier:getTier(id,shiny,mega,boss)||tier;const rarity=eggRarityForTier(tier);
  let p;try{p=window.createCapturedPoke?.(id,rarity,shiny,false,mega)}catch(x){}
  if(!p)p={id,name:window.getPokeName(id),level:1,hp:100,maxHp:100,atk:30,def:20,evoMult:evoBaseline(id),shiny,isMega:mega,isBoss:boss,rarity:{...rarity}};
  p.level=1;p.exp=0;p.shiny=shiny;p.isMega=mega;p.isBoss=boss;p.rarity={...rarity};p.tier=tier;p.forceTier=((e.kind==='special'&&e.value!=='shiny')||['SSS','UR','UR+','UR++'].includes(e.tier))?tier:undefined;
  if(mega)p.name=`${shiny?'Shiny Mega ':'Mega '}${window.getPokeName(id)}`;else if(shiny)p.name=`Shiny ${window.getPokeName(id)}`;else p.name=window.getPokeName(id);
  p.eggSource=true;p.evoMult=Math.max(Number(p.evoMult||1),evoBaseline(id));try{window.recalcPoke?.(p)}catch(x){}p.hp=p.maxHp;
  const need=typeof psySpecialUseReq==='function'?psySpecialUseReq(p):1;p.trainerUseLevel=need;
  if(need>(P.trainerLevel||1))P.box.push(p);else if(P.team.length<6)P.team.push(p);else P.box.push(p);
  P.meta.eggHatches=Number(P.meta.eggHatches||0)+1;save();try{window.renderTeam?.()}catch(x){}return p
}

